package localchat;
import java.nio.file.*;import java.util.*;import javax.swing.*;
/** Full LocalChat send -> parent -> delegated agents -> final reply, with a synthetic endpoint. */
public final class AgentIntegrationTest {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
 static String delegate(){return PdfAgentTest.request("team","run_agents",Json.obj("tasks",List.of(Json.obj("title","PDF","task","Check assigned synthetic PDF only."),Json.obj("title","Pairs","task","Check assigned synthetic V/W pairs only."))));}
 /** Waits (bounded) until the asynchronous parent/child/consolidation chain has fully landed in the UI; the assertions that follow are unchanged. */
 static void settle(LocalChat app,FeatureTest.Server server,int requests,String finalText)throws Exception{long end=System.nanoTime()+30_000_000_000L;while(true){boolean[] ready={false};FeatureTest.edt(()->ready[0]=server.requests.size()>=requests&&AttachmentTest.state(app).usage.requests>=requests&&((JTextPane)FeatureTest.field(app,"transcript")).getText().contains(finalText));if(ready[0]){FeatureTest.idle(app);return;}if(System.nanoTime()>end)return;Thread.sleep(25);}}
 static boolean tool(Object request,String name){Object specs=Json.get(request,"tools");return specs instanceof List<?> list&&list.stream().anyMatch(t->name.equals(Json.str(t,"function","name")));}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-");
  try{try(var server=new FeatureTest.Server(FeatureTest.json(delegate()),FeatureTest.json(FeatureTest.answer("PDF child complete",30,5)),FeatureTest.json(FeatureTest.answer("Pairs child complete",30,5)),FeatureTest.json(FeatureTest.answer("Consolidated final",70,10)))){
   LocalChat[] app={null};FeatureTest.edt(()->{app[0]=AttachmentTest.window(home,server.url());((JComboBox<String>)FeatureTest.field(app[0],"modelBox")).setSelectedItem("any-future-provider-model");});NormalModeTest.ask(app[0],"Porneste doi agenti pentru verificari independente, fara modificari.");settle(app[0],server,4,"Consolidated final");
   FeatureTest.edt(()->{check(server.requests.size()==4,"one parent request, two child requests, one consolidation");check(server.requests.stream().allMatch(r->"any-future-provider-model".equals(Json.str(r,"model"))),"all agents inherit arbitrary selected model");check(tool(server.requests.get(0),"run_agents"),"explicit request exposes delegation");check(!tool(server.requests.get(1),"run_agents")&&!tool(server.requests.get(2),"run_agents"),"children cannot delegate recursively");check(AttachmentTest.state(app[0]).usage.requests==4,"billing usage includes child requests exactly once");check(((JTextPane)FeatureTest.field(app[0],"transcript")).getText().contains("Consolidated final"),"final answer appears in parent chat");var log=NormalModeTest.history(app[0]);check(log.stream().anyMatch(m->m.role.equals("tool")&&m.content.contains("completed_tools")),"child outcomes retained in parent archive");check(log.stream().filter(m->m.role.equals("user")).count()==1,"child tasks do not become parent user messages");app[0].dispose();});
  }
  try(var server=new FeatureTest.Server(FeatureTest.json(FeatureTest.answer("Plain MBS response",10,3)),FeatureTest.json(FeatureTest.answer("Normal response",10,3)))){
   LocalChat[] app={null};FeatureTest.edt(()->app[0]=AttachmentTest.window(home.resolve("without-delegation"),server.url()));NormalModeTest.ask(app[0],"Continua verificarile existente.");check(!tool(server.requests.get(0),"run_agents"),"ordinary continuation never exposes delegation");FeatureTest.edt(()->NormalModeTest.mode(app[0],false));NormalModeTest.ask(app[0],"Porneste agenti pentru o intrebare generala");check(Json.get(server.requests.get(1),"tools")==null,"Normal stays clean without tool definitions");FeatureTest.edt(()->app[0].dispose());
  }
  FeatureTest.edt(()->{LocalChat app=AttachmentTest.window(home.resolve("partial-pdf"),"http://127.0.0.1:1/v1");Path report=home.resolve("partial-pdf/RAPPORT.pdf");Files.writeString(report,"synthetic existing PDF reference");String result=Json.write(Json.obj("group_id","group","status","partial","tasks",List.of(Json.obj("title","PDF","status","done","deliveries",List.of(Json.obj("job_id","verified","status","done","delivery_verified",true,"report",report.toString()))),Json.obj("title","Other","status","failed"))));var history=NormalModeTest.history(app);history.add(ChatClient.Message.user("Verifica prin agenti"));history.add(ChatClient.Message.assistant("",List.of(new ChatClient.ToolCall("g","run_agents",Json.obj("tasks",List.of()))),"fixture"));history.add(ChatClient.Message.toolResult("g",result,true));FeatureTest.call(app,"renderHistory",new Class<?>[]{});DefaultComboBoxModel<Path> reports=FeatureTest.field(app,"reportModel");check(reports.getSize()==1&&reports.getElementAt(0).equals(report.toRealPath()),"partial agent group preserves verified PDF card on history reload");app.dispose();});
  System.out.println("PASS: "+checks+" full-chat runtime agent integration checks; arbitrary selected model, consolidated final and actual usage");
  }finally{FeatureTest.edt(()->{for(var w:java.awt.Window.getWindows())w.dispose();});}System.exit(0);
 }
}
